#include <stdio.h>
#include <stdlib.h>

#define MAX_OBSERVERS 10

typedef struct Observer {
    int id;
    void (*notify)(int event);
} Observer;

typedef struct {
    Observer *observers[MAX_OBSERVERS];
    int count;
} Subject;

void subject_init(Subject *s) { s->count = 0; }
void subject_register(Subject *s, Observer *o) {
    if (s->count < MAX_OBSERVERS) s->observers[s->count++] = o;
}
void subject_notify(Subject *s, int event) {
    for (int i = 0; i < s->count; i++)
        s->observers[i]->notify(event);
}

void observer1_notify(int e) { printf("Observer 1 got event %d\n", e); }
void observer2_notify(int e) { printf("Observer 2 got event %d\n", e); }

int main() {
    Subject s; subject_init(&s);
    Observer o1 = {1, observer1_notify};
    Observer o2 = {2, observer2_notify};
    subject_register(&s, &o1);
    subject_register(&s, &o2);
    subject_notify(&s, 42);
    return 0;
}
